// #4b397a (6a993d6b51347e00464b397a) — домен «התמודדות עם ההתנגדות» в отчёте: одно состояние, 6 точек по отдельности,
// немедленная скидка — наблюдение «לא הודגם בשיחה» с цитатой, а не «פסילה» и не балл; без возражения — «אין מספיק מידע
// להערכה» с причиной. Кейсы REP-003, REP-004.
// По ГОТОВЫМ отчётам (новых звонков нет): QA-4b397a-DISC-2110 (звонок 116 с, скидка «…רק תסגור איתי היום») и отчёт без
// возражения «QA-AUTO-REC-…-gipo» (QA_NO_OBJECTION_CANDIDATE). Только чтение → @prod-safe.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { openReport } from './support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#4b397a · #6a993d6b51347e00464b397a';
const DISCOUNT_CANDIDATE = process.env.QA_DISCOUNT_CANDIDATE || 'QA-4b397a-DISC-2110';
const NO_OBJECTION_CANDIDATE: string | RegExp = process.env.QA_NO_OBJECTION_CANDIDATE || /^QA-AUTO-REC-\d+-gipo$/;
const CHECKPOINTS = [
  ['identifying_objection', 'זיהוי ההתנגדות'],
  ['inquiring_behind_objection', 'בירור מה עומד מאחוריה'],
  ['responding_to_customer', 'תגובה בהתאם לדברי הלקוח'],
  ['relevant_value', 'הצגת ערך רלוונטי'],
  ['adapting_offer', 'התאמת ההצעה'],
  ['no_automatic_response_or_discount', 'הימנעות מתגובה אוטומטית או מהנחה מיידית'],
] as const;
const STATES = ['clearly_demonstrated', 'partially_demonstrated', 'not_demonstrated', 'insufficient_information'];

test.describe(`Отчёт — домен возражения (${HASH})`, () => {
  test(`${DISCOUNT_CANDIDATE}: одно состояние домена, 6 точек, скидка — «לא הודגם בשיחה» с цитатой «רק תסגור איתי היום»; нет «פסילה» и балла @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openReport(page, DISCOUNT_CANDIDATE);
    const domain = page.locator('[data-testid="report-domain"][data-domain="objection"]');
    await expect(domain, 'домен «התמודדות עם ההתנגדות»').toHaveCount(1);
    await expect(domain.getByRole('heading', { level: 3 })).toContainText('התמודדות עם ההתנגדות');

    // Источник: AC1 — одно состояние домена + объяснение.
    const state = domain.locator(':scope > header [data-testid="domain-state"]');
    await expect(state).toHaveCount(1);
    expect(STATES).toContain(await state.getAttribute('data-state'));
    await expect(domain.getByTestId('domain-explanation')).not.toBeEmpty();

    // Источник: AC2 — шесть точек оцениваются раздельно: у каждой своё состояние и объяснение.
    const points = domain.getByTestId('checkpoint');
    await expect(points).toHaveCount(CHECKPOINTS.length);
    for (const [i, [key, label]] of CHECKPOINTS.entries()) {
      const p = points.nth(i);
      await expect(p).toHaveAttribute('data-checkpoint', key);
      await expect(p.getByRole('heading', { level: 4 })).toHaveText(label);
      await expect(p.getByTestId('checkpoint-state')).toHaveCount(1);
      await expect(p.getByTestId('checkpoint-explanation')).not.toBeEmpty();
    }

    // Источник: AC3 — немедленная скидка без выяснения = наблюдение, подкреплённое цитатой.
    const discount = domain.locator('[data-testid="checkpoint"][data-checkpoint="no_automatic_response_or_discount"]');
    await expect(discount.getByTestId('checkpoint-state')).toHaveAttribute('data-state', 'not_demonstrated');
    await expect(discount.getByTestId('checkpoint-state')).toHaveText('לא הודגם בשיחה');
    await expect(discount.getByTestId('evidence-quote').filter({ hasText: 'רק תסגור איתי היום' }).first()).toBeVisible();

    // Источник: AC3 «ולא כפסילה»; FL-42 — без балла и вывода о непригодности.
    const text = (await domain.innerText()).replace(/תחום \d+ מתוך 4:/, '');
    expect(text).not.toMatch(/פסיל|נפסל|ציון/);
    expect(text, 'балл вида N/M, «N מתוך M» или процент').not.toMatch(/\d+\s*\/\s*\d+|\d+\s*מתוך\s*\d+|\d+\s*%/);
  });

  test(`отчёт без возражения: домен «אין מספיק מידע להערכה» и причина «ההתנגדות שהוגדרה בתרחיש לא עלתה בשיחה» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openReport(page, NO_OBJECTION_CANDIDATE);
    const domain = page.locator('[data-testid="report-domain"][data-domain="objection"]');
    await expect(domain).toHaveCount(1);
    // Источник: AC4, треб. 5 — «אין מספיק מידע להערכה» и явная причина.
    const state = domain.locator(':scope > header [data-testid="domain-state"]');
    await expect(state).toHaveAttribute('data-state', 'insufficient_information');
    await expect(state).toHaveText('אין מספיק מידע להערכה');
    await expect(domain.getByTestId('domain-explanation')).toContainText('ההתנגדות שהוגדרה בתרחיש לא עלתה בשיחה');
  });
});
